            this.adjList.set(v2, 
                this.adjList.get(v2).filter(e => e.node !== v1));
        }
    }

    getNeighbors(vertex) {
        return this.adjList.get(vertex) || [];
    }

    getVertices() {
        return Array.from(this.adjList.keys());
